<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{NativePortAdapter,ProtectedPanel};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
require_once __DIR__.'/../fixtures/printify-connector/batch6/SyntheticNativeCore.php';
final class PrintifyCompanionBatch7Test extends TestCase {
 private function fixture():array {[$s]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$c=new SyntheticNativeCore();$c->operations->operationState='UNKNOWN';return [$s,$c,new ProtectedPanel(new NativePortAdapter($c))];}
 public function testInspectionRequiresExactCurrentSubjectAndRevision():void {[$s,$c,$p]=$this->fixture();$ctx=$c->context('unknown');$item=$p->snapshot($s,1,$ctx)['items'][0];$r=$p->inspect($s,1,$ctx,$item['subject_hash'],$item['review_revision']);self::assertIsArray($r);self::assertSame('UNKNOWN',$r['item']['operation_state']);self::assertFalse($r['external_execution_authorized']);self::assertFalse($r['retry_permitted']);self::assertInstanceOf(WP_Error::class,$p->inspect($s,1,$ctx,str_repeat('0',64),$item['review_revision']));self::assertInstanceOf(WP_Error::class,$p->inspect($s,1,$ctx,$item['subject_hash'],$item['review_revision']+1));}
 public function testRendererShowsScopeBlockersAndNoExecutionControls():void {[$s,$c,$p]=$this->fixture();$html=$p->render($s,1,$c->context('unknown'));self::assertStringContainsString('UNKNOWN',$html);self::assertStringContainsString('Review revision',$html);self::assertStringContainsString('No provider execution',$html);foreach(['<form','<button','<script','csrf_token','synthetic-nonce']as $v)self::assertStringNotContainsString($v,$html);}
 /** @dataProvider deniedFaults */
 public function testFaultsFailClosedWithoutLeakingEvidence(string $fault):void {[$s,$c,$p]=$this->fixture();$c->fault=$fault;self::assertInstanceOf(WP_Error::class,$p->snapshot($s,1,$c->context('unknown')));self::assertStringNotContainsString('UNKNOWN',$p->render($s,1,$c->context('unknown')));}
 public static function deniedFaults():array {return array_map(static fn($x)=>[$x],['revoked','wrong_version','wrong_spec','missing_capability','stale_authority','missing_journal','wrong_row_shop','expired','private_export']);}
 public function testMissingCoreCannotRenderProtectedRecords():void {[$s,$c]=$this->fixture();$p=new ProtectedPanel(new NativePortAdapter());self::assertInstanceOf(WP_Error::class,$p->snapshot($s,1,$c->context('unknown')));}
 public function testStaleQueueCheckpointIsDenied():void {[$s,$c,$p]=$this->fixture();self::assertIsArray($p->snapshot($s,1,$c->context('unknown')));$c->operations->epoch++;self::assertInstanceOf(WP_Error::class,$p->snapshot($s,1,$c->context('unknown')));}
 public function testAllViewsAndInspectionNeverCallWritePorts():void {[$s,$c,$p]=$this->fixture();foreach(['publication','orders','fulfillment','conflicts','unknown']as $view){$ctx=$c->context($view);$r=$p->snapshot($s,1,$ctx);self::assertIsArray($r);$p->render($s,1,$ctx);$p->export($s,1,$ctx);foreach($r['items']as $i)$p->inspect($s,1,$ctx,$i['subject_hash'],$i['review_revision']);}self::assertSame(0,$c->writeCalls);self::assertTrue($c->safetyStop);self::assertTrue($c->externalLock);}
 public function testRevocationDuringSnapshotCannotReturnRows():void {[$s,$c,$p]=$this->fixture();$checks=0;$c->actorCheck=static function()use(&$checks){return ++$checks<4;};self::assertInstanceOf(WP_Error::class,$p->snapshot($s,1,$c->context('unknown')));self::assertSame(0,$c->writeCalls);}
 public function testConflictsAndUnknownRemainReadOnlyAcrossRepeatedInspection():void {foreach(['UNKNOWN'=>'unknown','CONFLICTING'=>'conflicts']as $state=>$view){[$s,$c,$p]=$this->fixture();$c->operations->operationState=$state;$ctx=$c->context($view);$i=$p->snapshot($s,1,$ctx)['items'][0];for($n=0;$n<2;$n++){$r=$p->inspect($s,1,$ctx,$i['subject_hash'],$i['review_revision']);self::assertSame($state,$r['item']['operation_state']);self::assertSame($i['review_revision'],$r['item']['review_revision']);self::assertFalse($r['exception']['resolution_authorized']);}self::assertSame(0,$c->writeCalls);}}
}
